(698386, 73840, 19608, '<td valign="top">Very simple yet effective.</td>', 'Very simple yet effective.', '2004-05-05 02:22:11.000000', NULL, 1),
(698389, 73297, 19608, '<td valign="top">Nice framing.  Lighting was not your friend - take this same shot as close to sundown as you can.</td>', 'Nice framing.  Lighting was not your friend - take this same shot as close to sundown as you can.', '2004-05-05 02:23:05.000000', NULL, 1),
