(699494, 73790, 13136, '<td valign="top">Almost too much. I like the lighting (contrast) and the composition.</td>', 'Almost too much. I like the lighting (contrast) and the composition.', '2004-05-05 14:06:32.000000', NULL, 1),
(699495, 74420, 9821, '<td valign="top">very interesting to look at ... good job</td>', 'very interesting to look at ... good job', '2004-05-05 14:06:32.000000', NULL, 1),
