(699508, 74398, 19545, '<td valign="top">good idea</td>', 'good idea', '2004-05-05 14:10:38.000000', NULL, 1),
(699509, 73506, 1368, '<td valign="top">I like this picture,nice red color against the b&amp;w background,  would mabey have cropped a bit more of the top to have equally much space at the top and bottom (isnt very much though) Good luck :)</td>', 'I like this picture,nice red color against the b&w background,  would mabey have cropped a bit more of the top to have equally much space at the top and bottom (isnt very much though) Good luck :)', '2004-05-05 14:10:55.000000', NULL, 1),
(699510, 74199, 13136, '<td valign="top">To be honest, the rust is not very prominent. Seems like there is a slight patch in one place on the tool. Good humor.</td>', 'To be honest, the rust is not very prominent. Seems like there is a slight patch in one place on the tool. Good humor.', '2004-05-05 14:11:23.000000', NULL, 1),
(699511, 74477, 16488, '<td valign="top">Very nice lighting and exposure.  It feels a little off because the perspective tips everything to the right.  Subject has appeal.</td>', 'Very nice lighting and exposure.  It feels a little off because the perspective tips everything to the right.  Subject has appeal.', '2004-05-05 14:11:23.000000', NULL, 1),
(699513, 74385, 1368, '<td valign="top">Good composition, could mabey use a bit more contrast?</td>', 'Good composition, could mabey use a bit more contrast?', '2004-05-05 14:11:35.000000', NULL, 1),
(699514, 74302, 19545, '<td valign="top">nice composition</td>', 'nice composition', '2004-05-05 14:12:36.000000', NULL, 1),
