(699517, 73735, 13136, '<td valign="top">For me, the DOF is too tight with the wood out of focus. Also, with "Screw" in the title, maybe it should not have the side chopped off? Good texture on the rusted part though.</td>', 'For me, the DOF is too tight with the wood out of focus. Also, with "Screw" in the title, maybe it should not have the side chopped off? Good texture on the rusted part though.', '2004-05-05 14:13:07.000000', NULL, 1),
(699518, 74045, 19311, '<td valign="top">Maybe a little too much rust in the title, but still a fine picture with beatiful colors</td>', 'Maybe a little too much rust in the title, but still a fine picture with beatiful colors', '2004-05-05 14:13:26.000000', NULL, 1),
(699519, 74541, 13136, '<td valign="top">Unique perspective.</td>', 'Unique perspective.', '2004-05-05 14:13:29.000000', NULL, 1),
