(699539, 73791, 13136, '<td valign="top">Needs more contrast and looser cropping. It would help if it was larger also.</td>', 'Needs more contrast and looser cropping. It would help if it was larger also.', '2004-05-05 14:21:23.000000', NULL, 1),
(699540, 74353, 1368, '<td valign="top">This is so cute! The colors are adorable! Great work :)</td>', 'This is so cute! The colors are adorable! Great work :)', '2004-05-05 14:21:37.000000', NULL, 1),
