(699546, 74455, 13136, '<td valign="top">I think I would rather see some focus on the rail instead of the scenery.</td>', 'I think I would rather see some focus on the rail instead of the scenery.', '2004-05-05 14:22:41.000000', NULL, 1),
(699548, 73750, 13136, '<td valign="top">Use ''em more and they won''t get rusty.</td>', 'Use ''em more and they won''t get rusty.', '2004-05-05 14:23:44.000000', NULL, 1),
(699549, 73315, 9089, '<td valign="top">How about this for a title, "Rusty Wood Worms"</td>', 'How about this for a title, "Rusty Wood Worms"', '2004-05-05 14:23:57.000000', NULL, 1),
