(701435, 74539, 20027, '<td valign="top">Nice textures. Seems a bit washed out or under exposed. If your software allows, I would bump up the saturation a bit.</td>', 'Nice textures. Seems a bit washed out or under exposed. If your software allows, I would bump up the saturation a bit.', '2004-05-06 09:41:55.000000', NULL, 1),
(701436, 73269, 10702, '<td valign="top">Nice shot - like the DOF and how rusty and durty it is.</td>', 'Nice shot - like the DOF and how rusty and durty it is.', '2004-05-06 09:42:17.000000', NULL, 1),
(701438, 73805, 20204, '<td valign="top">Too much grass in the bottom half detracts from the tower.  I think it would have been nice to see the frame which surrounds the container more centered.</td>', 'Too much grass in the bottom half detracts from the tower.  I think it would have been nice to see the frame which surrounds the container more centered.', '2004-05-06 09:42:52.000000', NULL, 1),
