(703269, 73212, 21158, '<td valign="top">good</td>', 'good', '2004-05-07 01:05:15.000000', NULL, 1),
(703274, 73938, 21158, '<td valign="top">a little too bright on shank.</td>', 'a little too bright on shank.', '2004-05-07 01:07:21.000000', NULL, 1),
