INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(704227, 73321, 19831, '<td valign="top">how long did you have to wait for the bird? or just lucky? :D  ... nice shot.</td>', 'how long did you have to wait for the bird? or just lucky? :D  ... nice shot.', '2004-05-07 13:53:33.000000', NULL, 1),
(704235, 74391, 16488, '<td valign="top">Did you forget the lemon garnish?  Cute play on words.  Decently rendered pic.  Focus on the nailhead seems a bit soft and the highlights are a tad harsh, though.</td>', 'Did you forget the lemon garnish?  Cute play on words.  Decently rendered pic.  Focus on the nailhead seems a bit soft and the highlights are a tad harsh, though.', '2004-05-07 13:57:04.000000', NULL, 1),
(704236, 74050, 19831, '<td valign="top">seems blurry, hard to tell with small size. (see forum thread - Q &amp; A size doesn''t matter-myth) also, background seems kind of distracting.</td>', 'seems blurry, hard to tell with small size. (see forum thread - Q & A size doesn''t matter-myth) also, background seems kind of distracting.', '2004-05-07 13:57:41.000000', NULL, 1),
(704238, 73330, 16488, '<td valign="top">Nice close up of tinsnips (?).  This has an interesting abstract quality about it.  Think the color is a little overdone--too unreal for my tastes.  Think the background in the upper right could be cropped out, it doesn''t seem to add anything.</td>', 'Nice close up of tinsnips (?).  This has an interesting abstract quality about it.  Think the color is a little overdone--too unreal for my tastes.  Think the background in the upper right could be cropped out, it doesn''t seem to add anything.', '2004-05-07 13:58:58.000000', NULL, 1),
(704241, 73807, 19831, '<td valign="top">very nice. compelling, it makes me want to know the story.</td>', 'very nice. compelling, it makes me want to know the story.', '2004-05-07 13:59:22.000000', NULL, 1),
(704243, 74294, 16488, '<td valign="top">Nice idea for the subject--seems to be a "story" here.  Just a bit too overexposed and somewhat grainy to no good effect.  (IMHO)</td>', 'Nice idea for the subject--seems to be a "story" here.  Just a bit too overexposed and somewhat grainy to no good effect.  (IMHO)', '2004-05-07 14:00:17.000000', NULL, 1),
(704245, 74034, 19831, '<td valign="top">very nice detail. good shot.</td>', 'very nice detail. good shot.', '2004-05-07 14:00:27.000000', NULL, 1),
(704249, 73923, 16488, '<td valign="top">Well, the title says it all, doesn''t it?  There are some interesting shapes here--I like the repetition of the circles.  Not sure about the cropping and the leaves seem overexposed.</td>', 'Well, the title says it all, doesn''t it?  There are some interesting shapes here--I like the repetition of the circles.  Not sure about the cropping and the leaves seem overexposed.', '2004-05-07 14:02:36.000000', NULL, 1),
(704253, 74236, 19831, '<td valign="top">focus is off. whole thing seems kind of drab. the little red pole is quite distracting.</td>', 'focus is off. whole thing seems kind of drab. the little red pole is quite distracting.', '2004-05-07 14:04:44.000000', NULL, 1),
(704254, 73140, 18389, '<td valign="top">Not sure what this has to do with rusted.</td>', 'Not sure what this has to do with rusted.', '2004-05-07 14:05:37.000000', NULL, 1),
(704257, 74536, 3032, '<td valign="top">Great colors and pattern. It looks like something smashed into the screen and left a splattering pattern. Very interesting.</td>', 'Great colors and pattern. It looks like something smashed into the screen and left a splattering pattern. Very interesting.', '2004-05-07 14:06:39.000000', NULL, 1),
(704260, 74402, 18389, '<td valign="top">Too small.  Would have prefered to have the light shining on the front of the trash can.  The pole behind is also distracting.</td>', 'Too small.  Would have prefered to have the light shining on the front of the trash can.  The pole behind is also distracting.', '2004-05-07 14:10:00.000000', NULL, 1),
