(704810, 74044, 21291, '<td valign="top">What an brilliant photo in composition and title.  Excellent job!</td>', 'What an brilliant photo in composition and title.  Excellent job!', '2004-05-07 19:52:43.000000', NULL, 1),
(704812, 74536, 21061, '<td valign="top">I find this image is a bit too dark although it is a very appropriate subject.</td>', 'I find this image is a bit too dark although it is a very appropriate subject.', '2004-05-07 19:53:30.000000', NULL, 1),
(704815, 73385, 21061, '<td valign="top">That bolt has well and truly had its day!</td>', 'That bolt has well and truly had its day!', '2004-05-07 19:54:48.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(704821, 74374, 21061, '<td valign="top">I find that yhe DOF is too narrow on this image and causes it to lose perspective. Try a higher f-stop</td>', 'I find that yhe DOF is too narrow on this image and causes it to lose perspective. Try a higher f-stop', '2004-05-07 19:58:35.000000', NULL, 1),
(704824, 74438, 21061, '<td valign="top">I love water shots and this one is nice. Eventhough the rusted rails are nicely focused your eyes are drawn to the waterfall as it has been framed by the rails when the focus of this subject should be the rusty rails. Good luck.</td>', 'I love water shots and this one is nice. Eventhough the rusted rails are nicely focused your eyes are drawn to the waterfall as it has been framed by the rails when the focus of this subject should be the rusty rails. Good luck.', '2004-05-07 20:02:32.000000', NULL, 1),
(704828, 73790, 21061, '<td valign="top">Nice colours and great DOF.</td>', 'Nice colours and great DOF.', '2004-05-07 20:07:06.000000', NULL, 1),
(704843, 74275, 4153, '<td valign="top">I find the house in the background a bit distracting</td>', 'I find the house in the background a bit distracting', '2004-05-07 20:20:10.000000', NULL, 1),
(704844, 73449, 4153, '<td valign="top">I would have loved the whole head in focus :o)</td>', 'I would have loved the whole head in focus :o)', '2004-05-07 20:20:43.000000', NULL, 1),
(704845, 73724, 4153, '<td valign="top">is this Hagrids sword, looks huge :oþ</td>', 'is this Hagrids sword, looks huge :oþ', '2004-05-07 20:21:26.000000', NULL, 1),
(704846, 74502, 4153, '<td valign="top">nice framing, maybe just a tad too thick, maybe not :o)</td>', 'nice framing, maybe just a tad too thick, maybe not :o)', '2004-05-07 20:22:33.000000', NULL, 1),
(704850, 73528, 21061, '<td valign="top">nice abstract!</td>', 'nice abstract!', '2004-05-07 20:23:21.000000', NULL, 1),
