(706997, 73861, 18191, '<td valign="top">I like the DOF here...nice shot...</td>', 'I like the DOF here...nice shot...', '2004-05-09 14:04:39.000000', NULL, 1),
(706998, 74539, 1792, '<td valign="top">Seems a little over exposed, but composition and depth of field are effective.</td>', 'Seems a little over exposed, but composition and depth of field are effective.', '2004-05-09 14:04:49.000000', NULL, 1),
