INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(708146, 74368, 19831, '<td valign="top">a nice shot, but I find it kind of busy, hard to find your solid focal point.</td>', 'a nice shot, but I find it kind of busy, hard to find your solid focal point.', '2004-05-10 02:42:50.000000', NULL, 1),
(708379, 73233, 8013, '<td valign="top">Would of been nice to get a bit lower and closer to get none or less of the background in the shot!  Nice colours though - the rust looks good.</td>', 'Would of been nice to get a bit lower and closer to get none or less of the background in the shot!  Nice colours though - the rust looks good.', '2004-05-10 06:34:26.000000', NULL, 1),
(708380, 74472, 8013, '<td valign="top">Hard to see what it is!</td>', 'Hard to see what it is!', '2004-05-10 06:35:06.000000', NULL, 1),
(708382, 73539, 14202, '<td valign="top">this photo really works for me...great depth and use of natural lighting...well done = 9</td>', 'this photo really works for me...great depth and use of natural lighting...well done = 9', '2004-05-10 06:39:50.000000', NULL, 1),
(708385, 73644, 8013, '<td valign="top">Not my idea of rusted, but nice photo anyhow.  Nice DOF and detail on the flower.</td>', 'Not my idea of rusted, but nice photo anyhow.  Nice DOF and detail on the flower.', '2004-05-10 06:40:36.000000', NULL, 1),
