(711185, 74348, 17505, '<td valign="top">Cute. Good eye.</td>', 'Cute. Good eye.', '2004-05-11 11:47:14.000000', NULL, 1),
(711186, 73889, 20204, '<td valign="top">Not enough contrat in the design elements to make this stand out.</td>', 'Not enough contrat in the design elements to make this stand out.', '2004-05-11 11:47:15.000000', NULL, 1),
